registered as (insert into public.english_word_questions(id,version,sentence,choices,answer,credit_sentence)
 select id,1,sentence,choices,answer,sentence from taught on conflict(id,version) do nothing)
insert into public.english_classroom_question_catalogue(question_id) select id from taught;

-- Keep the installed host, student and scoring logic. Narrow only the next-turn query.
do $migration$
declare
  definition text := pg_get_functiondef('public.english_classroom(text,uuid,jsonb)'::regprocedure);
  source text := 'from public.english_word_questions candidate';
  scoped_source text := source || ' join public.english_classroom_question_catalogue taught on taught.question_id = candidate.id';
begin
  if position(scoped_source in definition) = 0 then
    if position(source in definition) = 0 then
      raise exception 'Classroom turn selector changed; review its eligibility query before migration.';
    end if;
    execute replace(definition, source, scoped_source);
  end if;
end;
$migration$;
commit;
